/// `TABLES[size_bucket_index][weight_index]` -- `weight_index` is 0 for
/// [`FontWeight::Normal`], 1 for [`FontWeight::Bold`] (see [`weight_index`]).
pub const TABLES: [[SizeWeightTable; 2]; 5] = [
    [SizeWeightTable { cell_w: 6, cell_h: 12, ascii: &SIZE12_NORMAL_ASCII, latin1: &SIZE12_NORMAL_LATIN1 }, SizeWeightTable { cell_w: 6, cell_h: 12, ascii: &SIZE12_BOLD_ASCII, latin1: &SIZE12_BOLD_LATIN1 }],
    [SizeWeightTable { cell_w: 8, cell_h: 16, ascii: &SIZE16_NORMAL_ASCII, latin1: &SIZE16_NORMAL_LATIN1 }, SizeWeightTable { cell_w: 8, cell_h: 16, ascii: &SIZE16_BOLD_ASCII, latin1: &SIZE16_BOLD_LATIN1 }],
    [SizeWeightTable { cell_w: 10, cell_h: 20, ascii: &SIZE20_NORMAL_ASCII, latin1: &SIZE20_NORMAL_LATIN1 }, SizeWeightTable { cell_w: 10, cell_h: 20, ascii: &SIZE20_BOLD_ASCII, latin1: &SIZE20_BOLD_LATIN1 }],
    [SizeWeightTable { cell_w: 12, cell_h: 24, ascii: &SIZE24_NORMAL_ASCII, latin1: &SIZE24_NORMAL_LATIN1 }, SizeWeightTable { cell_w: 12, cell_h: 24, ascii: &SIZE24_BOLD_ASCII, latin1: &SIZE24_BOLD_LATIN1 }],
    [SizeWeightTable { cell_w: 16, cell_h: 32, ascii: &SIZE32_NORMAL_ASCII, latin1: &SIZE32_NORMAL_LATIN1 }, SizeWeightTable { cell_w: 16, cell_h: 32, ascii: &SIZE32_BOLD_ASCII, latin1: &SIZE32_BOLD_LATIN1 }],
];

fn weight_index(weight: FontWeight) -> usize {
    match weight {
        FontWeight::Normal => 0,
        FontWeight::Bold => 1,
    }
}

/// Nearest-bucket resolution used ONLY internally by [`lookup`] -- callers are
/// expected to already have snapped `size_px` via
/// `text::terminus::nearest_terminus_size` (the canonical, extensively-tested
/// tie-break/clamp rule) before reaching here, so this only ever needs to find
/// the EXACT matching bucket; the simple nearest-by-absolute-difference search
/// below is a defensive fallback for totality (never panics on an unexpected
/// `size_px`), not a second copy of the canonical snap contract.
fn bucket_index(size_px: f32) -> usize {
    if !size_px.is_finite() {
        return 1; // defined finite default: the 16px bucket
    }
    let mut best = 0usize;
    let mut best_diff = f32::INFINITY;
    for (i, &s) in SIZES.iter().enumerate() {
        let diff = (size_px - s).abs();
        if diff < best_diff {
            best_diff = diff;
            best = i;
        }
    }
    best
}

/// Look up one glyph: total over all of `char` (never panics) -- a scalar
/// outside the 191-glyph subset (`0x20..=0x7E` or `0xA0..=0xFF`) resolves to
/// [`FALLBACKS`]'s hollow box at the same bucket's cell size, rather than
/// vanishing. `size_px` is resolved to a bucket via [`bucket_index`] --see
/// that function's own doc comment for why it does its own (defensive,
/// non-canonical) nearest-match rather than re-implementing
/// `text::terminus::nearest_terminus_size`'s tie-break rule.
pub fn lookup(size_px: f32, weight: FontWeight, ch: char) -> Glyph {
    let idx = bucket_index(size_px);
    let table = &TABLES[idx][weight_index(weight)];
    let code = ch as u32;
    let rows = if (0x20..=0x7E).contains(&code) {
        table.ascii[(code - 0x20) as usize]
    } else if (0xA0..=0xFF).contains(&code) {
        table.latin1[(code - 0xA0) as usize]
    } else {
        FALLBACKS[idx]
    };
    Glyph { cell_w: table.cell_w, cell_h: table.cell_h, rows }
}

